<script lang="ts">
 import type{Project}from '../model';
 import {design,areaStats,energy,economics,price,num}from '../engine/calculate';
 import BarChart from './BarChart.svelte';
 export let project:Project;
 export let onExport:()=>void=()=>{};
 $: d=design(project);$: a=areaStats(project);$: en=energy(project,d);$: ec=economics(project,d,en);
 function toCSV(){const rows=[['Equipment','Model','Qty','UnitPrice_Rial','Total_Rial'],['Panel',d.panel?.model||'',d.installedPanels,project.panelPrice,d.installedPanels*project.panelPrice],['Inverter',d.inverter?.model||'',d.inverters,project.inverterPrice,d.inverters*project.inverterPrice],...project.extras.map(x=>[x.type,x.title,x.quantity,x.unitPrice,x.quantity*x.unitPrice])];const text='\ufeff'+rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\r\n');const blob=new Blob([text],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='SolarEstimator_BOQ.csv';a.click();URL.revokeObjectURL(url);}
</script>
